import sys
from collections import defaultdict

def dfs(node, parent, colors, graph, depth, path):
    path[node] = depth
    for neighbor in graph[node]:
        if neighbor != parent:
            dfs(neighbor, node, colors, graph, depth + 1, path)

def lca(u, v, parent, depth, path):
    while path[u] < path[v]:
        v = parent[v]
    while path[v] < path[u]:
        u = parent[u]
    while u != v:
        u = parent[u]
        v = parent[v]
    return u

def has_rgb_on_path(u, v, lca_node, colors, parent, depth, path):
    def check_path(x, y):
        while x != y:
            if colors[x - 1] in 'RG':
                return True
            x = parent[x]
        return False
    return check_path(u, lca_node) or check_path(v, lca_node)

def process_test_case():
    N = int(sys.stdin.readline())
    C = sys.stdin.readline().strip()
    graph = defaultdict(list)
    for _ in range(N - 1):
        u, v = map(int, sys.stdin.readline().split())
        graph[u].append(v)
        graph[v].append(u)
    parent = {1: None}
    depth = {1: 0}
    path = {1: 0}
    dfs(1, None, C, graph, 0, path)
    queue = [1]
    while queue:
        node = queue.pop()
        for neighbor in graph[node]:
            if neighbor not in parent:
                parent[neighbor] = node
                depth[neighbor] = depth[node] + 1
                path[neighbor] = path[node] + 1
                queue.append(neighbor)
    blue_nodes = [i for i in range(1, N + 1) if C[i - 1] == 'B']
    for i in range(len(blue_nodes)):
        for j in range(i + 1, len(blue_nodes)):
            u, v = blue_nodes[i], blue_nodes[j]
            lca_node = lca(u, v, parent, depth, path)
            if not has_rgb_on_path(u, v, lca_node, C, parent, depth, path):
                return 'No'
    return 'Yes'

T = int(sys.stdin.readline())
results = []
for _ in range(T):
    results.append(process_test_case())
print('\n'.join(results))
